export async function ensureModelSelection(Runtime, desiredModel, logger, strategy = "select", options = {}) {
    if (strategy === "select" && /^GPT[- ]6[- ]Pro$/i.test(desiredModel)) {
        const { ensurePowerPicker } = await import("./power-picker.mjs");
        const selected = await ensurePowerPicker(Runtime, desiredModel, "pro");
        if (!selected?.verified) throw new Error("GPT-6 Pro selection was not verified.");
        logger(`Model picker: ${selected.label}`);
        return { requestedModel: desiredModel, resolvedLabel: selected.label, strategy,
            status: selected.status, verified: true, source: selected.source,
            capturedAt: new Date().toISOString() };
    }

export async function ensureThinkingTime(Runtime, level, logger, desiredModel) {
    const { ensurePowerPicker } = await import("./power-picker.mjs");
    const selectedPower = await ensurePowerPicker(Runtime, desiredModel, level);
    if (selectedPower?.verified) {
        logger(`[browser] Thinking time: ${selectedPower.label} (Power ${selectedPower.power + 1}/5 verified)`);
        return;
    }
